raw_text:
{
  "narratives": [
    {
      "item_code": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "start": "p2:L2",
      "end": "p2:L4"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start": "p2:L5",
      "end": "p2:L7"
    },
    {
      "item_code": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "start": "p2:L8",
      "end": "p2:L10"
    },
    {
      "item_code": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "start": "p2:L11",
      "end": "p2:L13"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "start": "p2:L14",
      "end": "p2:L15"
    }
  ],
  "extras": [
    {
      "after_item": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "눈을 문지르지 마시오.",
          "line": "p2:L3"
        },
        {
          "value": "많은 양의 물을 사용하여 적어도 15분 동안 눈을 씻어내시오.",
          "line": "p2:L4"
        }
      ],
      "line": "p2:L2"
    },
    {
      "after_item": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "오염된 의복 및 신발을 벗고 즉시 적어도 15분 동안 비누와 물로 씻어내시오.",
          "line": "p2:L6"
        },
        {
          "value": "오염된 피복은 재사용 전에 (충분히) 세탁하시오",
          "line": "p2:L7"
        }
      ],
      "line": "p2:L5"
    },
    {
      "after_item": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "다량의 증기나 미스트에 노출되었을 경우 맑은 공기가 있는 곳으로 이동하시오.",
          "line": "p2:L9"
        },
        {
          "value": "필요에 따른 조치를 취하시오.",
          "line": "p2:L10"
        }
      ],
      "line": "p2:L8"
    },
    {
      "after_item": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "구토를 유발해야 하는지에 대해서 의사의 조언을 받으시오.",
          "line": "p2:L12"
        },
        {
          "value": "즉시 물로 입을 씻어내시오.",
          "line": "p2:L13"
        }
      ],
      "line": "p2:L11"
    },
    {
      "after_item": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "reason": "코드없음",
      "statements": [
        {
          "value": "오염상황을 의료관계자에게 알려 그들도 적절한 보호조치를 취하도록 하시오.",
          "line": "p2:L15"
        }
      ],
      "line": "p2:L14"
    }
  ]
}

